 lines.append('| {idx} | {storm} {time} {mission} | {center}；{flag} | {cover} | {rmw} | {r80} ({r80c}) | {rmax} ({rmaxc}) | {shift} | {maxc} | {w1}; {direction} | {ind} | {reldiff} |'.format(idx=idx+1,storm=a['storm'],time=a['time_utc'],mission=a['mission'],center=where,flag=qualflag,cover=f(a.get('coverage_0_2rmw')),rmw=(cell(main)+(' 是' if a.get('winning_ring_truncated') else ' 否')) if main is not None else '—',r80=cell(a.get('rmw_80_km')),r80c=f(a.get('rmw_80_relative_change')),rmax=cell(a.get('analysis_rmax_km')),rmaxc=f(a.get('rmax_relative_change')),shift=shift,maxc=f(a.get('max_relative_change')),w1=f(a.get('wave1_fraction')),direction=f(a.get('wave1_peak_deg_north_cw'),1),ind=independent,reldiff=f(rel) if idx==1 else '—'))
